TLM.f("Sancti/09-29",{"officium":"In Dedicatione S. Michælis Archangelis","rule":["ex Sancti/05-08","Gloria","Credo"],"ruleInherited":["Gloria","CredoDA"],"fallback":"Sancti/05-08","sections":{"Introitus":[{"k":"ref","la":"Ps 102:20"},{"k":"text","la":"Benedícite Dóminum, omnes Angeli ejus: poténtes virtúte, qui fácitis verbum ejus, ad audiéndam vocem sermónum ejus."},{"k":"ref","la":"Ps 102:1"},{"k":"text","la":"Benedic, ánima mea, Dómino: et ómnia, quæ intra me sunt, nómini sancto ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Benedícite Dóminum, omnes Angeli ejus: poténtes virtúte, qui fácitis verbum ejus, ad audiéndam vocem sermónum ejus."}],"Oratio":[{"k":"text","la":"Deus, qui, miro ordine, Angelórum ministéria hominúmque dispénsas: concéde propítius; ut, a quibus tibi ministrántibus in cœlo semper assístitur, ab his in terra vita nostra muniátur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Apocalýpsis beáti Joánnis Apóstoli"},{"k":"ref","la":"Apoc 1:1-5"},{"k":"text","la":"In diébus illis: Significávit Deus, quæ opórtet fíeri cito, mittens per Angelum suum servo suo Joánni, qui testimónium perhíbuit verbo Dei, et testimónium Jesu Christi, quæcúmque vidit. Beátus, qui legit et audit verba prophetíæ hujus: et servat ea, quæ in ea scripta sunt: tempus enim prope est. Joánnes septem ecclésiis, quæ sunt in Asia. Grátia vobis et pax ab eo, qui est et qui erat et qui ventúrus est: et a septem spirítibus, qui in conspéctu throni ejus sunt: et a Jesu Christo, qui est testis fidélis, primogénitus mortuórum et princeps regum terræ, qui diléxit nos et lavit nos a peccátis nostris in sánguine suo."}],"Graduale":[{"k":"ref","la":"Ps 102:20; 102:1"},{"k":"text","la":"Benedícite Dóminum, omnes Angeli ejus: poténtes virtúte, qui fácitis verbum ejus."},{"k":"text","la":"Benedic, ánima mea, Dóminum, et ómnia interióra mea, nomen sanctum ejus.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Sancte Míchaël Archángele, defénde nos in prœ́lio: ut non pereámus in treméndo judício. Allelúja.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 18:1-10"},{"k":"text","la":"In illo témpore: Accessérunt discípuli ad Jesum, dicéntes: Quis, putas, major est in regno cœlórum? Et ádvocans Jesus párvulum, státuit eum in médio eórum et dixit: Amen, dico vobis, nisi convérsi fuéritis et efficiámini sicut párvuli, non intrábitis in regnum cœlórum. Quicúmque ergo humiliáverit se sicut párvulus iste, hic est major in regno cœlórum. Et qui suscéperit unum párvulum talem in nómine meo, me súscipit. Qui autem scandalizáverit unum de pusíllis istis, qui in me credunt, expédit ei, ut suspendátur mola asinária in collo ejus, et demergátur in profúndum maris. Væ mundo a scándalis! Necésse est enim, ut véniant scándala: verúmtamen væ hómini illi, per quem scándalum venit! Si autem manus tua vel pes tuus scandalízat te, abscíde eum et projíce abs te: bonum tibi est ad vitam ingrédi débilem vel claudum, quam duas manus vel duos pedes habéntem mitti in ignem ætérnum. Et si óculus tuus scandalízat te, érue eum et projice abs te: bonum tibi est cum uno óculo in vitam intráre, quam duos óculos habéntem mitti in gehénnam ignis. Vidéte, ne contemnátis unum ex his pusíllis: dico enim vobis, quia Angeli eórum in cœlis semper vident fáciem Patris mei, qui in cœlis est."}],"Offertorium":[{"k":"ref","la":"Apoc 8:3; 8:4"},{"k":"text","la":"Stetit Angelus juxta aram templi, habens thuríbulum áureum in manu sua, et data sunt ei incénsa multa: et ascendit fumus arómatum in conspéctu Dei, allelúja."}],"Secreta":[{"k":"text","la":"Hóstias tibi, Dómine, laudis offérimus, supplíciter deprecántes: ut eásdem, angélico pro nobis interveniénte suffrágio, et placátus accípias, et ad salútem nostram proveníre concédas."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Dan 5:58"},{"k":"text","la":"Benedícite, omnes Angeli Dómini, Dóminum: hymnum dícite et superexaltáte eum in sǽcula, allelúja."}],"Postcommunio":[{"k":"text","la":"Beáti Archángeli tui Michaélis intercessióne suffúlti: súpplices te, Dómine, deprecámur; ut, quod ore proséquimur, contingámus et mente."},{"k":"macro","name":"Per Dominum"}]},"hr":{"92504dc00afe8cf8":{"t":"Ps 102, 20, Ps 102, 1\n(Ps 102, 20) Blagoslivljajte Gospodina svi anđeli njegovi, silni krepošću koji izvršavate riječ njegovu slušajući glas besjeda njegovih. (Ps 102, 1) Blagoslivljaj, dušo moja, Gospodina, i sve što je u meni njegovo sveto ime.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 102, 20) Blagoslivljajte Gospodina svi anđeli njegovi, silni krepošću koji izvršavate riječ njegovu slušajući glas besjeda njegovih.","kn":"(Ps. 102, 20), Blagosivajte Goispodlna svi anđeli njegovi, koji ste silni krepošću i izvršujete riječ njegovu slušajući glas besjeda njegovih. (Ps. 102, 1) Blagosivaj, dušo moja. Gospodina., i sve što je u meni, sveto ime njegovo. Slava Ocu . . . Blagosivajte . .","knRef":"Kniewald 1942, str. 530–531 (snimka 266) (OCR)"},"5f55046fc42fe6f7":{"t":"<i>Pomolimo se</i>.\nBože, koji divnim redom dijeliš službe anđela i ljudi, podaj milostivo da nam čuvaju život na zemlji oni koji te vazda dvore na nebu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Milostivi Bože, koji divnim redom dijeliš službe anđela i ljudi: podaj, da nam čuvaju život na zemlji oni, koji Te vazda dvore na nebu; ipo G.:n","knRef":"Kniewald 1942, str. 718–719 (snimka 360) (OCR)"},"060d2f3d07a1860b":{"t":"Otk 1, 1-5\nČitanje knjige Otkrivenja blaženog Ivana apostola. U one dane, Bog je označio što se ima skoro dogoditi i po svojem anđelu objavi svojemu slugi Ivanu, koji je posvjedočio onome, koji čita i sluša riječi ovoga proročanstva, i drži se onoga, što je napisano u njemu, jer je vrijeme blizu. Ivan sedmerim crkvama u Aziji: Milost vam i mir od onoga, koji jest, koji je bio i koji će doći, i od sedam duhova, koji su pred njegovim prijestoljem, i od Isusa Krista, koji je vjeran svjedok, prvorođenac od mrtvih i vladar zemaljskih kraljeva, koji nas ljubi i koji nas je svojom krvlju oprao od naših grijeha.","kn":"Čitanje Knjige otkrivenja bi. Ivana apostola (1, 1-5). U one dane označio je Bog, što se brzo dogodi i po svomu je anđelu objavio svomu sluzi Ivanu, koji je posvjedočio sve, što je vidio o riječi Božjoj i o Isusu Kristu. Blago onomu, koji čita i sluša riječi ovoga proroštva i drži se onoga, što je u njemu napisano, jer je vrijeme blizu. Ivan sedmerim crkvama, koje su u Aziji: Milost. i mir vama od onoga, koji jest, koji je bio i koji će biti 1 od sedam duhova, koji su pred njegovim prijestoljem, i od Isusa Krista, koji je vjerni svjedok, prvorođenac od mrtvih i knez nad zemaljslclm kraljevima, koji nas je ljubio i od naših nas grijeha oprao svojom krvlju.","knRef":"Kniewald 1942, str. 720–721 (snimka 361) (OCR)"},"80a85afbbabc8226":{"t":"Ps 102, 20 i 1\nBlagoslivljajte Gospodina svi anđeli njegovi, silni krepošću koji izvršavate riječ njegovu. Blagoslivljaj, dušo moja, Gospodina i sve što je u meni njegovo sveto ime.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nSveti arkanđele Mihaele, brani nas u boju, ne daj da propadnemo na strašnom sudu. <i>Aleluja</i>.","kn":"(Ps. 102, 20). Blagosiljajte Gospodina svi anđeli njegovi, silni krepošću, koji izvršujete riječ njegovu. BlagO:Slovi, dušo moja, Gospodina, 1 sve što je u meni ime sveto njegovo.\n\nAleluja, aleluja. Sveti Mihovile arhanđele, brani nas u boju, da ne poginemo na strašnom sudu, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 720–721 (snimka 361) (OCR)"},"6237683989f4e4c3":{"t":"Mt 18, 1-10\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme, pristupe učenici k Isusu i upitaju ga: Što misliš, tko je najveći u nebeskom kraljevstvu? Isus nato pozva jedno malo dijete, postavi ga pred njih i reče: Zaista vam kažem: ako se ne obratite i ne postanete kao,djeca, nećete ući u nebesko kraljevstvo. Dakle, tko se ponizi kao ovo dijete, taj je najveći u nebeskom kraljevstvu. I još vam kažem: tko radi mene primi jedno dijete kao što je ovo, mene prima. A tko sablazni jednoga od ovih malenih, koji vjeruju u mene, bilo bi mu bolje, da mu se oko vrata objesi mlinski kamen i da potone u morskoj dubini. Jao svijetu od sablazni! Sablazni treba da dođu, ali jao onome po kojem dolazi sablazan! Ako ti je na sablazan tvoja ruka ili tvoja noga, odsijeci je i baci, jer ti je bolje da uđeš u život kljast ili hrom nego da imaš obje ruke ili noge i da te bace u vječni oganj. I ako ti je na sablazan tvoje oko, iskopaj ga, jer ti je bolje da s jednim okom uđeš u život nego da imaš oba oka i bace te u ognjeni pakao. Pazite da ne prezirete ni jednoga od ovih malenih, jer vam kažem, da njihovi anđeli na nebu uvijek gledaju lice mojega nebeskog Oca.","v":"ista misa na staroj stranici, latinski tekst odstupa (sličnost 1.00)","kn":"† Slijedi sv. evanđelje po Mateju (18, 1-10).\nU ono vrijeme pristupiše k Isusu njegovi učenici i upitaše ga: Što misliš, tko je najveći u kraljevstvu nebeskom? Isus tada pozove dijete, postavi ga pred njih i odgovori: Zaista vam kažem: Ako se ne obratite i ne postanete kao djeca, ne ćete ući u kraljevstvo nebesko! Koji postane malen kao ovo dijete, taj je najveći u kraljevstvu nebeskom. I koji primi radi mene jedno takvo dijete mene prima. A koji sablazni jednoga od ovih malih, koji vjeruju u mene, bolje bi mu bilo, da mu se objesi oko vrata mlinski kamen i da potone u morsku dubinu. Jao svijetu radi sablazni! Treba da dođu sablazni, ali jao onom čovjeku, po kojemu dolazi sablazan. Ako ti je na sablazan tvoja ruka ili tvoja noga, odsijeci je i odbaci, jer ti je bolje ući u život sakatu i hromu, nego da imaš obje ruke ili obje noge i da te bace u vječni oganj. I ako ti je na sablazan oko, iskopaj ga i odbaci, jer ti je bolje ući u život s jednim okom, nego da imaš oba oka i da te bace u ognjeni pakao. Pazite, da ne prezrete jednoga od ovih malih, jer kažem vam, da njihovi anđeli na nebu uvijek gledaju lice moga nebeskog Oca.","knRef":"Kniewald 1942, str. 720-721"},"5d7a7f6b890c06f0":{"t":"Otk 8, 3 i 4\nStade anđeo uz žrtvenik hrama držeći zlatnu kadionicu u svojoj ruci, i dadoše mu mnogo tamjana, i uziđe dim od mirisa pred lice Božje, <i>aleluja</i>.","kn":"(Otkr. 8). Stade anđeo uz žrtvenik hrama, držeći zlatnu kadionicu u ruci svojoj, i dadoše mu mnogo kadila i uziđe dim od mirisa pred lice Božje. Aleluja.","knRef":"Kniewald 1942, str. 720–721 (snimka 361) (OCR)"},"4dafcf4bb2236e02":{"t":"Prikazujemo ti, Gospodine, žrtve hvale smjerno moleći, da ih na zagovor anđela i milostivo primiš i podaš da nam budu korisne za naše spasenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Prikazujemo Ti, Gospodine, žrtve hvale, smjerno se moleći, da ih anđeoskim zagovorom umilostivl j en primiš i podaš, da nam uspiju za naše spasenje. Po .G. n.","knRef":"Kniewald 1942, str. 720–721 (snimka 361) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"47f83a22e44dfb92":{"t":"Dn 3, 58\nBlagoslivljajte Gospodina, svi anđeli Gospodnji, pjevajte pjesmu i uzvisujte ga u vijeke, <i>aleluja</i>.","v":"∅ → aleluia","kn":"(Dan. 3, 58). Blagosiljajte svi anđeli Go.spodnji Gospodina, pjesmu recite i uzvisujte. ga u vijeke, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 720–721 (snimka 361) (OCR)"},"989394c367ea0417":{"t":"<i>Pomolimo se</i>.\nOslonivši se na zagovor tvoga svetog arkanđela Mihaela smjerno te, Gospodine, molimo da i dušom obuhvatimo što ustima primamo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Oslonivši se na zagovor Tvoga svetog arkanđela Mihovila ponizno Te, Gospodine, molimo, da i dušom obuhvatimo,, što ustima primamo, po G. n. ;","knRef":"Kniewald 1942, str. 720–721 (snimka 361) (OCR)"},"adad0f7f2fcbfa9b":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi. Gospodine, sveti Oče, svemogući vječni Bože. – Ti si s jedinorođenim Sinom tvojim i s Duhom Svetim jedan Bog, jedan Gospodin, ne u jedinstvu jedne osobe, već u Trojstvu jedine biti. Što naime po tvojoj objavi vjerujemo o tvojoj slavi, to isto bez razlike i razlučivanja vjerujemo i o tvome Sinu i o Duhu Svetome. Tako se u ispovijedanju istinitog i vjekovječnog božanstva klanjamo i vlastitosti osoba i jedinstvu biti i jednakosti veličanstva. – Koje hvale anđeli i arkanđeli, kerubini i serafini koji ne prestaju svaki dan klicati govoreći složnim glasom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Go. spodine sveti, Oće svemogući, vječni Bože, koji si sa Sinom svojim i s Duhom Svetim jedan Bog i je- dan Gospodin: ne u jedinstvu osobe, nego u Trojstvu jedne biti. Jer sve, što po Tvojem otkrivenju vjerujemo o Tvojoj slavi, to bez razlike i razlučivanja mislimo i o Sinu Tvoj emu i o Duhu Svetomu. Ispovijedajući pravo i vječno Božanstvo, klanjamo se tako i vlastitosti u osobama i jedinstvu u biti i jednakosti u veličanstvu, koje hvale anđeli i arkanđeli, kerubini i serafini, koji ne prestaju klicati svakog dana jednoglasno govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"}}});
